import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ============================================
  // CORE STATE
  // ============================================
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [myPhone, setMyPhone] = useState('0712345678');
  const [isFirstTimeUser, setIsFirstTimeUser] = useState(true);
  const [showWelcomeBack, setShowWelcomeBack] = useState(false);
  const [registrationError, setRegistrationError] = useState('');
  const [userExistsError, setUserExistsError] = useState(false);
  const [showMainMenu, setShowMainMenu] = useState(false);
  const [registrationComplete, setRegistrationComplete] = useState(false);
  const [activationKeyword, setActivationKeyword] = useState('');
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [showSystemResponse, setShowSystemResponse] = useState(false);
  const [systemResponseMessage, setSystemResponseMessage] = useState('');
  const [showSuccessScreen, setShowSuccessScreen] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [successTitle, setSuccessTitle] = useState('');
  const [isCompleteProfileStep, setIsCompleteProfileStep] = useState(false);

  // ============================================
  // DASHBOARD STATE
  // ============================================
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [currentRequestIndex, setCurrentRequestIndex] = useState(0);
  const [myMatches, setMyMatches] = useState([]);
  const [currentMatchListIndex, setCurrentMatchListIndex] = useState(0);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [isSendingMessage, setIsSendingMessage] = useState(false);
  const [searchCriteria, setSearchCriteria] = useState({ 
    gender: '', ageFrom: '', ageTo: '', county: '', town: '', religion: '', education: '' 
  });
  const [matchOffset, setMatchOffset] = useState(0);
  const [totalMatches, setTotalMatches] = useState(0);
  const [isSearching, setIsSearching] = useState(false);
  const [hasMoreMatches, setHasMoreMatches] = useState(false);
  const [favorites, setFavorites] = useState([]);
  const [showFavorites, setShowFavorites] = useState(false);

  // ============================================
  // CHAT STATE
  // ============================================
  const [chatContacts, setChatContacts] = useState([]);
  const [chatMessages, setChatMessages] = useState({});
  const [newMessage, setNewMessage] = useState('');
  const [selectedChatContact, setSelectedChatContact] = useState(null);

  // ============================================
  // STATS
  // ============================================
  const [stats, setStats] = useState({
    totalMatches: 0,
    pendingRequests: 0,
    acceptedMatches: 0,
    unreadMessages: 0,
    favorites: 0,
    profileCompletion: 0
  });

  // ============================================
  // SMS SYSTEM MESSAGES
  // ============================================
  const SYSTEM_MESSAGES = {
    activation: `Welcome to our dating service with 6000 potential dating partners!\n\nTo register, enter the following details:\nstart#name#age#gender#county#town\n\nExample:\nstart#John Doe#26#Male#Nakuru#Naivasha`,
    registrationSuccess: (name) => `Your profile has been created successfully ${name}.\n\nSMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.\nE.g. details#diploma#driver#single#christian#mijikenda`,
    detailsSuccess: `This is the last stage of registration. SMS a brief description of yourself to 22141 starting with the word MYSELF.\nE.g., MYSELF chocolate, lovely, sexy etc.`,
    detailsNotProvided: `You were registered for dating with your initial details.\nTo search for a MPENZI, SMS match#age#town to 22141\nE.g., match#23-25#Nairobi`,
    selfDescriptionSuccess: `You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141 and meet the person of your dreams.\nE.g., match#23-25#Kisumu`,
    interestSent: (name) => `Your interest request has been sent successfully to ${name}.\n\nThe other member will be notified.`,
    requestAccepted: (name) => `Congratulations! You have accepted ${name}'s request.\n\nYou may now begin chatting.`
  };

  // ============================================
  // SAMPLE DATA
  // ============================================
  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', description: 'Kind-hearted and adventurous. Loves hiking and reading.', compatibility: 85 },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', county: 'Nakuru County', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Caring and dedicated. Loves children and education.', compatibility: 78 },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', county: 'Mombasa County', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', marital_status: 'single', description: 'Ambitious and hardworking. I love numbers.', compatibility: 92 },
    { id: 4, phone: '0722040506', name: 'Pamela Nafula', age: 26, town: 'Kisumu', county: 'Kisumu County', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', description: 'Tech enthusiast. Loves innovation and building solutions.', compatibility: 70 },
    { id: 5, phone: '0702556677', name: 'Maria Mwende', age: 28, town: 'Kasarani', county: 'Nairobi County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kamba', marital_status: 'single', description: 'Diligent, loving, dedicated and will make you tick.', compatibility: 88 },
    { id: 6, phone: '0708990011', name: 'Keziah Cheptab', age: 28, town: 'Eldoret', county: 'Uasin Gishu County', profession: 'Doctor', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', description: 'Passionate about healthcare and community service.', compatibility: 75 }
  ];

  const SAMPLE_MORE_MATCHES = [
    { id: 7, phone: '0711000001', name: 'Jane Wanjiru', age: 25, town: 'Thika', county: 'Kiambu County', profession: 'Designer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Creative and artistic.', compatibility: 82 },
    { id: 8, phone: '0711000002', name: 'Sarah Akinyi', age: 31, town: 'Kisumu', county: 'Kisumu County', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Passionate about justice.', compatibility: 68 }
  ];

  const SAMPLE_REQUESTS = [
    { id: 101, phone: '0723000001', name: 'Michael Ochieng', age: 30, town: 'Nairobi', county: 'Nairobi County', profession: 'Lawyer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-15' },
    { id: 102, phone: '0723000002', name: 'David Kiprop', age: 28, town: 'Eldoret', county: 'Uasin Gishu County', profession: 'Businessman', education: 'Graduate', religion: 'Christian', ethnicity: 'Kalenjin', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-14' },
    { id: 103, phone: '0723000003', name: 'Samuel Mwangi', age: 32, town: 'Nakuru', county: 'Nakuru County', profession: 'Developer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', message: '💕 Shows interest in you', status: 'pending', date: '2024-01-13' }
  ];

  const SAMPLE_MY_MATCHES = [
    { id: 201, phone: '0724000001', name: 'Grace Akinyi', age: 27, town: 'Kisumu', county: 'Kisumu County', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Luo', marital_status: 'single', status: 'accepted' },
    { id: 202, phone: '0724000002', name: 'Peter Mwangi', age: 29, town: 'Nakuru', county: 'Nakuru County', profession: 'Engineer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted' },
    { id: 203, phone: '0724000003', name: 'Sarah Wanjiru', age: 25, town: 'Thika', county: 'Kiambu County', profession: 'Designer', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', marital_status: 'single', status: 'accepted' }
  ];

  // ============================================
  // API CALL FUNCTIONS
  // ============================================
  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();
      console.log(`API ${method} ${endpoint}:`, data);
      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================
  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(true);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setMatchOffset(parsed.matchOffset || 0);
          setTotalMatches(parsed.totalMatches || 0);
          setFavorites(parsed.favorites || []);

          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================
  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu,
        searchCriteria,
        matchOffset,
        totalMatches,
        favorites
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, currentUser, isLoggedIn, phoneNumber, activationDone, allMatches, incomingRequests, myMatches, chatContacts, chatMessages, activeTab, myPhone, showMainMenu, searchCriteria, matchOffset, totalMatches, favorites]);

  // ============================================
  // UPDATE STATS
  // ============================================
  useEffect(() => {
    const profileFields = ['name', 'age', 'gender', 'county', 'town', 'education', 'profession', 'marital_status', 'religion', 'ethnicity', 'description', 'height', 'body_type', 'children', 'smoking', 'drinking', 'hobbies', 'about_me'];
    const filledFields = profileFields.filter(f => currentUser && currentUser[f]);
    const completion = Math.round((filledFields.length / profileFields.length) * 100);

    setStats({
      totalMatches: allMatches.length + myMatches.length,
      pendingRequests: incomingRequests.filter(r => r.status === 'pending').length,
      acceptedMatches: myMatches.length,
      unreadMessages: chatContacts.reduce((sum, c) => sum + (c.unread || 0), 0),
      favorites: favorites.length,
      profileCompletion: completion
    });
  }, [allMatches, incomingRequests, myMatches, chatContacts, favorites, currentUser]);

  // ============================================
  // CHECK SERVER
  // ============================================
  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPER FUNCTIONS
  // ============================================
  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / 4) * 100);
  };

  const buildSmsPreview = (step) => {
    if (step === 2) {
      return `start#${formData.name || 'Jamal Jalang\'o'}#${formData.age || '29'}#${formData.gender || 'Male'}#${formData.county || 'Mombasa'}#${formData.town || 'Bamburi'}`;
    }
    if (step === 3) {
      return `details#${formData.education_level || 'diploma'}#${formData.profession || 'driver'}#${formData.marital_status || 'single'}#${formData.religion || 'christian'}#${formData.ethnicity || 'mijikenda'}`;
    }
    if (step === 4) {
      return `MYSELF ${formData.description || 'tall, dark and handsome'}`;
    }
    return '';
  };

  const showSuccess = (title, message) => {
    setSuccessTitle(title);
    setSuccessMessage(message);
    setShowSuccessScreen(true);
  };

  // ============================================
  // LOGOUT / EXIT / HOME FUNCTIONS
  // ============================================
  const handleLogout = () => {
    localStorage.removeItem('penziState');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setAllMatches([]);
    setIncomingRequests([]);
    setMyMatches([]);
    setChatContacts([]);
    setChatMessages({});
    setSelectedChatContact(null);
    setActivationDone(false);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    setShowWelcomeBack(false);
    setIsFirstTimeUser(true);
    setUserExistsError(false);
    setRegistrationError('');
    setShowMainMenu(false);
    setRegistrationComplete(false);
    setActivationKeyword('');
    setMatchOffset(0);
    setTotalMatches(0);
    setShowSystemResponse(false);
    setSystemResponseMessage('');
    setShowSuccessScreen(false);
    setFavorites([]);
    addNotification('👋 Logged out successfully!');
  };

  const goHome = () => {
    setActiveTab('discover');
    setSelectedChatContact(null);
    setShowProfile(false);
    setShowMatchDetails(false);
    setSelectedMatch(null);
    setShowMainMenu(true);
    setShowFavorites(false);
    addNotification('🏠 Returned to home');
  };

  // ============================================
  // PROFILE VIEW FUNCTIONS
  // ============================================
  const viewProfile = async (match) => {
    const requesterPhone = currentUser?.phone || myPhone || '0712345678';
    const details = await callApi(`/${match.phone}/details?requester=${requesterPhone}`, 'GET');

    if (details && details.status === 'success') {
      setSelectedMatch({ ...match, ...details.data });
    } else {
      setSelectedMatch(match);
    }
    setShowMatchDetails(true);
  };

  const viewUserProfile = async (user) => {
    const requesterPhone = currentUser?.phone || myPhone || '0712345678';
    const details = await callApi(`/${user.phone}/details?requester=${requesterPhone}`, 'GET');

    if (details && details.status === 'success') {
      setSelectedMatch({ ...user, ...details.data });
    } else {
      setSelectedMatch(user);
    }
    setShowMatchDetails(true);
  };

  // ============================================
  // DASHBOARD FUNCTIONS
  // ============================================
  const toggleFavorite = (match) => {
    const exists = favorites.some(f => f.phone === match.phone);
    if (exists) {
      setFavorites(prev => prev.filter(f => f.phone !== match.phone));
      addNotification(`⭐ Removed ${match.name} from favorites`);
    } else {
      setFavorites(prev => [...prev, match]);
      addNotification(`⭐ Added ${match.name} to favorites`);
    }
  };

  const handleExpressInterest = async (targetPhone) => {
    const match = allMatches.find(m => m.phone === targetPhone) || 
                  favorites.find(f => f.phone === targetPhone);
    if (!match) {
      addNotification('❌ Match not found.', 'error');
      return;
    }

    setIsLoading(true);
    try {
      const fromPhone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi('/interest', 'POST', {
        fromPhone: fromPhone,
        toPhone: targetPhone
      });

      if (result && result.status === 'success') {
        const newRequest = {
          id: Date.now(),
          phone: match.phone,
          name: match.name,
          age: match.age,
          town: match.town,
          county: match.county,
          profession: match.profession,
          message: `💕 ${currentUser?.name || 'Someone'} is interested in you!`,
          status: 'pending',
          date: new Date().toISOString().split('T')[0]
        };
        setIncomingRequests(prev => [...prev, newRequest]);
        setAllMatches(prev => prev.filter(m => m.phone !== targetPhone));
        setFavorites(prev => prev.filter(f => f.phone !== targetPhone));
        showSuccess('💕 Interest Sent!', SYSTEM_MESSAGES.interestSent(match.name));
        addNotification(`💕 Interest sent to ${match.name}!`);
      } else {
        addNotification('❌ Failed to send interest. Please try again.', 'error');
      }
    } catch (error) {
      console.error('Interest error:', error);
      addNotification('❌ Error expressing interest.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi('/consent', 'POST', {
        phone: phone,
        targetPhone: request.phone,
        consent: 'YES'
      });

      if (result && result.status === 'success') {
        const newMatch = {
          id: Date.now(),
          phone: request.phone,
          name: request.name,
          age: request.age,
          town: request.town,
          county: request.county,
          profession: request.profession,
          status: 'accepted'
        };
        setMyMatches(prev => [...prev, newMatch]);
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        showSuccess('🎉 Request Accepted!', SYSTEM_MESSAGES.requestAccepted(request.name));
        addNotification(`✅ You accepted ${request.name}'s request!`);
      } else {
        addNotification('❌ Failed to accept request.', 'error');
      }
    } catch (error) {
      console.error('Accept request error:', error);
      addNotification('❌ Error accepting request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRejectRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi('/consent', 'POST', {
        phone: phone,
        targetPhone: request.phone,
        consent: 'NO'
      });

      if (result && result.status === 'success') {
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        addNotification(`❌ You declined ${request.name}'s request.`);
      } else {
        addNotification('❌ Failed to decline request.', 'error');
      }
    } catch (error) {
      console.error('Reject request error:', error);
      addNotification('❌ Error declining request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const performSearch = async () => {
    setIsSearching(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const { gender, ageFrom, ageTo, county, town, religion, education } = searchCriteria;

      let ageRange = '';
      if (ageFrom && ageTo) {
        ageRange = `${ageFrom}-${ageTo}`;
      } else if (ageFrom) {
        ageRange = `${ageFrom}-100`;
      } else if (ageTo) {
        ageRange = `18-${ageTo}`;
      }

      const result = await callApi('/match', 'POST', {
        phone: phone,
        gender: gender,
        ageRange: ageRange,
        town: town,
        county: county,
        religion: religion,
        education: education,
        offset: 0,
        limit: 10
      });

      if (result && result.status === 'success') {
        const matches = result.data?.matches || result.matches || [];
        const total = result.data?.total || result.total || 0;
        setTotalMatches(total);
        setAllMatches(matches);
        setHasMoreMatches(matches.length < total);
        if (matches.length > 0) {
          addNotification(`✅ Found ${matches.length} matches!`);
        } else {
          addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
        }
      } else {
        let filtered = SAMPLE_MATCHES;
        if (gender && gender !== '') {
          // Filter by gender (mock)
        }
        if (ageFrom || ageTo) {
          const from = parseInt(ageFrom) || 0;
          const to = parseInt(ageTo) || 100;
          filtered = filtered.filter(m => m.age >= from && m.age <= to);
        }
        if (town && town !== '') {
          filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
        }
        if (county && county !== '') {
          filtered = filtered.filter(m => m.county && m.county.toLowerCase().includes(county.toLowerCase()));
        }
        if (religion && religion !== '') {
          filtered = filtered.filter(m => m.religion && m.religion.toLowerCase().includes(religion.toLowerCase()));
        }
        if (education && education !== '') {
          filtered = filtered.filter(m => m.education && m.education.toLowerCase().includes(education.toLowerCase()));
        }
