              <button className="btn-primary" onClick={() => {
                setAllMatches(SAMPLE_MATCHES);
                setHasMoreMatches(true);
                addNotification(`✅ Loaded ${SAMPLE_MATCHES.length} matches!`);
              }}>
                📥 Load Sample Matches
              </button>
              <button className="btn-secondary" onClick={() => {
                resetSearch();
              }}>
                Modify Search
              </button>
              <button className="btn-secondary" onClick={() => setShowMainMenu(true)}>
                Main Menu
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="table-header">
              <div className="table-header-left">
                <h3>👥 Matching Profiles</h3>
                <span className="match-count">{allMatches.length} results</span>
              </div>
              <div className="table-header-right">
                {searchCriteria.gender && (
                  <span className="search-tag">Gender: {searchCriteria.gender}</span>
                )}
                {searchCriteria.ageFrom && searchCriteria.ageTo && (
                  <span className="search-tag">Age: {searchCriteria.ageFrom}-{searchCriteria.ageTo}</span>
                )}
                {searchCriteria.town && (
                  <span className="search-tag">Town: {searchCriteria.town}</span>
                )}
                {searchCriteria.county && (
                  <span className="search-tag">County: {searchCriteria.county}</span>
                )}
              </div>
            </div>

            <div className="matches-table-wrapper">
              <table className="matches-table">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Name</th>
                    <th>Age</th>
                    <th>Town</th>
                    <th>County</th>
                    <th>Occupation</th>
                    <th>Compatibility</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {allMatches.map((match, index) => (
                    <tr key={match.id} className="match-row">
                      <td className="match-number">{index + 1}</td>
                      <td className="match-name-cell">
                        <div className="match-avatar-small" onClick={() => viewProfile(match)}>
                          {match.name?.charAt(0) || '?'}
                        </div>
                        <span className="match-name-text" onClick={() => viewProfile(match)}>
                          {match.name}
                        </span>
                      </td>
                      <td>{match.age}</td>
                      <td>{match.town}</td>
                      <td>{match.county || 'N/A'}</td>
                      <td>{match.profession || 'N/A'}</td>
                      <td>
                        {match.compatibility && (
                          <span className={`compatibility-score ${match.compatibility >= 80 ? 'high' : match.compatibility >= 60 ? 'medium' : 'low'}`}>
                            {match.compatibility}%
                          </span>
                        )}
                      </td>
                      <td className="match-actions-cell">
                        <button className="btn-view" onClick={() => viewProfile(match)} title="View Profile">👁</button>
                        <button className="btn-interest" onClick={() => handleExpressInterest(match.phone)} title="Express Interest">❤️</button>
                        <button className="btn-save" onClick={() => toggleFavorite(match)} title="Save to Favorites">
                          {favorites.some(f => f.phone === match.phone) ? '⭐' : '☆'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="table-navigation">
              <button 
                className="nav-btn"
                onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 10))}
                disabled={currentMatchIndex === 0}
              >
                ⬅ Previous
              </button>
              <span className="match-counter">
                Showing {currentMatchIndex + 1} - {Math.min(currentMatchIndex + 10, allMatches.length)} of {allMatches.length}
              </span>
              <button 
                className="nav-btn"
                onClick={() => {
                  if (currentMatchIndex + 10 >= allMatches.length) {
                    if (hasMoreMatches) {
                      loadMoreMatches();
                    } else {
                      addNotification('ℹ️ No more matches available.', 'warning');
                    }
                  } else {
                    setCurrentMatchIndex(Math.min(allMatches.length - 1, currentMatchIndex + 10));
                  }
                }}
                disabled={isLoading}
              >
                {currentMatchIndex + 10 >= allMatches.length ? '📥 Load More' : 'Next ➡'}
              </button>
            </div>
          </>
        )}
      </div>
    );
  };

  // RENDER REQUESTS TABLE
  const renderRequestsTable = () => {
    if (incomingRequests.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">📬</div>
          <h2>No Requests</h2>
          <p>When someone shows interest in you, it will appear here</p>
          <button className="btn-primary" onClick={() => {
            setIncomingRequests(SAMPLE_REQUESTS);
            addNotification(`✅ Loaded ${SAMPLE_REQUESTS.length} requests!`);
          }}>
            📥 Load Demo Requests
          </button>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>📬 People Interested In You</h3>
            <span className="match-count">{incomingRequests.length} requests</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>Town</th>
                <th>County</th>
                <th>Message</th>
                <th>Date</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {incomingRequests.map((request, index) => (
                <tr key={request.id} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => viewProfile(request)}>
                      {request.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => viewProfile(request)}>
                      {request.name}
                    </span>
                  </td>
                  <td>{request.age}</td>
                  <td>{request.town}</td>
                  <td>{request.county || 'N/A'}</td>
                  <td className="request-message-cell">{request.message}</td>
                  <td>{request.date || 'Today'}</td>
                  <td><span className="status-pending">⏳ Pending</span></td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => viewProfile(request)}>👁</button>
                    <button className="btn-accept" onClick={() => handleAcceptRequest(request)}>✅ Accept</button>
                    <button className="btn-decline" onClick={() => handleRejectRequest(request)}>❌ Decline</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentRequestIndex(Math.max(0, currentRequestIndex - 5))}
            disabled={currentRequestIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentRequestIndex + 1} of {incomingRequests.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentRequestIndex(Math.min(incomingRequests.length - 1, currentRequestIndex + 5))}
            disabled={currentRequestIndex >= incomingRequests.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // RENDER MY MATCHES TABLE
  const renderMyMatchesTable = () => {
    if (myMatches.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">💕</div>
          <h2>No Matches Yet</h2>
          <p>Start discovering and accepting requests to find your match</p>
          <div className="empty-actions">
            <button className="btn-primary" onClick={() => {
              setMyMatches(SAMPLE_MY_MATCHES);
              addNotification(`✅ Loaded ${SAMPLE_MY_MATCHES.length} matches!`);
            }}>
              📥 Load Sample Matches
            </button>
            <button className="btn-secondary" onClick={() => setActiveTab('discover')}>
              🔍 Discover People
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>💕 Your Matches</h3>
            <span className="match-count">{myMatches.length} matches</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>Town</th>
                <th>County</th>
                <th>Profession</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {myMatches.map((match, index) => (
                <tr key={match.id} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => viewProfile(match)}>
                      {match.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => viewProfile(match)}>
                      {match.name}
                    </span>
                  </td>
                  <td>{match.age}</td>
                  <td>{match.town}</td>
                  <td>{match.county || 'N/A'}</td>
                  <td>{match.profession || 'N/A'}</td>
                  <td><span className="status-accepted">✅ Accepted</span></td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => viewProfile(match)}>👁</button>
                    <button className="btn-chat" onClick={() => startChat(match)}>💬 Chat</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.max(0, currentMatchListIndex - 5))}
            disabled={currentMatchListIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentMatchListIndex + 1} of {myMatches.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.min(myMatches.length - 1, currentMatchListIndex + 5))}
            disabled={currentMatchListIndex >= myMatches.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // RENDER FAVORITES
  const renderFavorites = () => {
    if (favorites.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">⭐</div>
          <h2>No Favorites</h2>
          <p>Save your favorite profiles by clicking the star icon</p>
          <button className="btn-primary" onClick={() => setActiveTab('discover')}>
            🔍 Discover People
          </button>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>⭐ Favorites</h3>
            <span className="match-count">{favorites.length} saved</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>County</th>
                <th>Compatibility</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {favorites.map((match, index) => (
                <tr key={match.id || index} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => viewProfile(match)}>
                      {match.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => viewProfile(match)}>
                      {match.name}
                    </span>
                  </td>
                  <td>{match.age}</td>
                  <td>{match.county || 'N/A'}</td>
                  <td>
                    {match.compatibility && (
                      <span className={`compatibility-score ${match.compatibility >= 80 ? 'high' : match.compatibility >= 60 ? 'medium' : 'low'}`}>
                        {match.compatibility}%
                      </span>
                    )}
                  </td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => viewProfile(match)}>👁</button>
                    <button className="btn-chat" onClick={() => startChat(match)}>💬</button>
                    <button className="btn-decline" onClick={() => toggleFavorite(match)}>⭐ Remove</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  // RENDER MAIN MENU
  const renderMainMenu = () => {
    const hasProfile = completedSteps.has(1);
    const hasDescription = completedSteps.has(2);

    return (
      <div className="main-menu-container">
        <div className="main-menu-header">
          <h1>💑 PENZI Dating</h1>
          <p className="menu-subtitle">Welcome back. Choose one of the options below.</p>
          {currentUser && (
            <div className="menu-user-info">
              <span>👋 Welcome, {currentUser.name || 'User'}!</span>
            </div>
          )}
        </div>

        <div className="dashboard-stats">
          <div className="stat-card matches">
            <span className="stat-icon">👥</span>
            <div className="stat-number">{stats.totalMatches}</div>
            <div className="stat-label">Total Matches</div>
          </div>
          <div className="stat-card requests">
            <span className="stat-icon">📬</span>
            <div className="stat-number">{stats.pendingRequests}</div>
            <div className="stat-label">Pending Requests</div>
          </div>
          <div className="stat-card accepted">
            <span className="stat-icon">💕</span>
            <div className="stat-number">{stats.acceptedMatches}</div>
            <div className="stat-label">Accepted Matches</div>
          </div>
          <div className="stat-card messages">
            <span className="stat-icon">💬</span>
            <div className="stat-number">{stats.unreadMessages}</div>
            <div className="stat-label">Unread Messages</div>
          </div>
        </div>

        <div className="main-menu-options">
          <div className="menu-card profile-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setShowProfile(true);
            setIsEditingProfile(false);
          }}>
            <div className="menu-card-icon">👤</div>
            <div className="menu-card-content">
              <h3>My Profile</h3>
              <p>View and edit your profile</p>
              {hasProfile && hasDescription && <span className="menu-card-badge">✅ Complete</span>}
              {(!hasProfile || !hasDescription) && <span className="menu-card-badge inactive">⏳ Incomplete</span>}
            </div>
          </div>

          <div className="menu-card matches-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            if (allMatches.length === 0) {
              setAllMatches(SAMPLE_MATCHES);
              setHasMoreMatches(true);
              addNotification(`✅ Found ${SAMPLE_MATCHES.length} matches!`);
            }
          }}>
            <div className="menu-card-icon">❤️</div>
            <div className="menu-card-content">
              <h3>Search Matches</h3>
              <p>Find your perfect partner</p>
              <span className="menu-card-sub">Search by: Age • Town • County</span>
            </div>
          </div>

          <div className="menu-card requests-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('requests');
            if (incomingRequests.length === 0) {
              setIncomingRequests(SAMPLE_REQUESTS);
            }
          }}>
            <div className="menu-card-icon">💌</div>
            <div className="menu-card-content">
              <h3>My Requests</h3>
              <p>People interested in you</p>
              {stats.pendingRequests > 0 && <span className="menu-card-badge">{stats.pendingRequests} new</span>}
            </div>
          </div>

          <div className="menu-card chat-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('chat');
          }}>
            <div className="menu-card-icon">💬</div>
            <div className="menu-card-content">
              <h3>Chats</h3>
              <p>Your conversations</p>
              {stats.unreadMessages > 0 && <span className="menu-card-badge">{stats.unreadMessages} unread</span>}
            </div>
          </div>

          <div className="menu-card favorites-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setShowFavorites(true);
          }}>
            <div className="menu-card-icon">⭐</div>
            <div className="menu-card-content">
              <h3>Favorites</h3>
              <p>Your saved profiles</p>
              {favorites.length > 0 && <span className="menu-card-badge">{favorites.length} saved</span>}
            </div>
          </div>

          <div className="menu-card logout-card" onClick={() => {
            if (window.confirm('Are you sure you want to exit PENZI Dating Service?')) {
              handleLogout();
            }
          }}>
            <div className="menu-card-icon">🚪</div>
            <div className="menu-card-content">
              <h3>Logout</h3>
              <p>Exit the application</p>
            </div>
          </div>
        </div>

        <div className="main-menu-footer">
          <span className="menu-version">v2.0 • PENZI Dating Service</span>
          <span className="menu-version">🔒 Secure • Private</span>
        </div>
      </div>
    );
  };

  // RENDER DASHBOARD
  const renderDashboard = () => {
    const hasRequests = incomingRequests.length > 0;
    const hasChatContacts = chatContacts.length > 0;

    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <button className="btn-home" onClick={goHome} title="Home">🏠</button>
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="btn-menu" onClick={() => setShowMainMenu(true)} title="Main Menu">📋</button>
            <button className="profile-btn" onClick={() => { setShowProfile(true); setIsEditingProfile(false); }} title="My Profile">👤</button>
            <button className="btn-exit" onClick={() => {
              if (window.confirm('Are you sure you want to exit PENZI Dating Service?')) {
                handleLogout();
              }
            }} title="Logout">🚪</button>
          </div>
        </header>

        <div className="dashboard-stats">
          <div className="stat-card matches">
            <span className="stat-icon">👥</span>
            <div className="stat-number">{stats.totalMatches}</div>
            <div className="stat-label">Total Matches</div>
          </div>
          <div className="stat-card requests">
            <span className="stat-icon">📬</span>
            <div className="stat-number">{stats.pendingRequests}</div>
            <div className="stat-label">Pending Requests</div>
          </div>
          <div className="stat-card accepted">
            <span className="stat-icon">💕</span>
            <div className="stat-number">{stats.acceptedMatches}</div>
            <div className="stat-label">Accepted Matches</div>
          </div>
          <div className="stat-card messages">
            <span className="stat-icon">💬</span>
            <div className="stat-number">{stats.unreadMessages}</div>
            <div className="stat-label">Unread Messages</div>
          </div>
        </div>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('discover');
              setShowFavorites(false);
              if (allMatches.length === 0) {
                setAllMatches(SAMPLE_MATCHES);
                setHasMoreMatches(true);
              }
            }}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('matches');
              setShowFavorites(false);
              if (myMatches.length === 0) {
                setMyMatches(SAMPLE_MY_MATCHES);
              }
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
              setShowFavorites(false);
              if (incomingRequests.length === 0) {
                setIncomingRequests(SAMPLE_REQUESTS);
              }
            }}
          >
            📬 Requests
            {hasRequests && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('chat');
              setShowFavorites(false);
            }}
          >
            💬 Chat
            {hasChatContacts && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'favorites' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('favorites');
              setShowFavorites(true);
            }}
          >
            ⭐ Favorites
            {favorites.length > 0 && <span className="nav-badge">{favorites.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && !showFavorites && renderDiscoverTable()}
          {activeTab === 'favorites' && renderFavorites()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================
  return (
    <div className="app">
      {renderNotifications()}

      {showSuccessScreen ? (
        renderSuccessScreen()
      ) : userExistsError ? (
        renderUserExistsWarning()
      ) : showWelcomeBack && !isLoggedIn ? (
        renderWelcomeBack()
      ) : isLoggedIn ? (
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : (
        activationDone ? (
          isCompleteProfileStep ? (
            renderCompleteProfile()
          ) : (
            renderRegistrationStep()
          )
        ) : (
          renderActivationPage()
        )
      )}
    </div>
  );
}

export default App;
